import logging
import queue
from threading import Thread
import time

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CatFileTransfer(object):
    """
    Base class for file transfer based on connecting "cat" processes on source and
    target host.
    """
    CHUNK_SIZE = 2 ** 20

    @staticmethod
    def _get_time():
        return time.time()

    @staticmethod
    def _read_from_stdout_and_write_to_stdin(error_queue, source_process, target_process):
        while True:
            data = source_process.stdout.read(size=CatFileTransfer.CHUNK_SIZE)
            if not data:
                return True
            try:
                target_process.stdin.write(data)
            except Exception as exception:
                error_queue.put("write exception: {exception!r}".format(exception=exception))
                return False

    @staticmethod
    def _kill_cat_process_using_executor_and_timestamp(process, executor, timestamp):
        if process.is_running:
            executor.execute(
                """bash -c 'path=$(cd /proc ;"""
                """ grep -l __={timestamp} */environ 2> /dev/null) ; """
                """[ "$path" ] || exit 0 ; """
                """pid=$(dirname $path) ; """
                """echo $pid ; """
                """kill $pid 2> /dev/null ; :'""".format(
                    timestamp=timestamp
                ).encode())
            while process.stdout.read(size=CatFileTransfer.CHUNK_SIZE):
                pass
            process.stderr.read()
            process.wait()

    @staticmethod
    def _log_warnings_from_error_queue(error_queue):
        while not error_queue.empty():
            logger.warning(error_queue.get())

    def _transfer_file(
            self,
            source_path,
            target_path,
            source_executor,
            target_executor):

        def run(error_queue, source_executor, target_executor,
                source_path, target_path):
            source_time = self._get_time()
            source_process = source_executor.start(
                """bash -c '__={source_time} cat "{source_path}"'""".format(
                    source_time=source_time,
                    source_path=source_path
                ).encode())
            target_time = self._get_time()
            target_process = target_executor.start(
                """bash -c '__={target_time} cat > "{target_path}"'""".format(
                    target_time=target_time,
                    target_path=target_path
                ).encode())
            write_succeeded = self._read_from_stdout_and_write_to_stdin(
                error_queue=error_queue,
                source_process=source_process,
                target_process=target_process)
            if not write_succeeded:
                self._kill_cat_process_using_executor_and_timestamp(
                    source_process,
                    source_executor,
                    source_time)
            for process in (source_process, target_process):
                process.stdin.close()
                while process.stdout.read(size=CatFileTransfer.CHUNK_SIZE):
                    pass
                stderr = process.stderr.read()
                process.wait()
                exit_status = process.exit_status
                if stderr or exit_status:
                    error_queue.put(
                        "error: command={command}, exit_status={exit_status} "
                        "stderr={stderr}".format(
                            command=process.command,
                            exit_status=exit_status,
                            stderr=stderr
                        ))

        error_queue = queue.Queue()
        thread = Thread(target=run,
                        args=(error_queue,
                              source_executor,
                              target_executor,
                              source_path,
                              target_path))
        thread.daemon = True
        thread.start()
        thread.join()
        self._log_warnings_from_error_queue(error_queue)
